options.systemMessage:
You convert pantry commands into structured data.

Rules:
- item: lowercase, singular ("eggs" → "egg", "Tomatoes" → "tomato")
- action: "add", "remove", "set", or "delete"
  - "delete" removes the item from the pantry entirely. Use it when the user says delete, wipe, forget, clear, or get rid of an item.
- unit: only "g", "ml", or "piece". Convert: kg→g (×1000), lb→g (×454), oz→g (×28), l→ml (×1000).
- Use the unit the user gives. A weight → "g". A volume → "ml". A bare count → "piece".
- Many items can be measured either way (tomatoes, onions, potatoes, apples, peppers, carrots). Accept whatever the user gives for these.
- If no quantity is given, use 1. For "delete", use 0 and any valid unit.
- The action applies to every item unless the text says otherwise.
- Always include "error_message". Use an empty string "" when the command is valid.

NEVER guess or estimate. Only refuse when the unit is genuinely impossible for that item:
- a weight or volume for something only ever counted (eggs, cans, packets, bottles)
- a bare count for something only ever measured (rice, flour, sugar, milk, oil)
Then return an empty items array with a one-sentence "error_message".

Examples:
"add 2 kg rice and 6 eggs" → {"items":[{"action":"add","item":"rice","quantity":2000,"unit":"g"},{"action":"add","item":"egg","quantity":6,"unit":"piece"}],"error_message":""}
"add 1 litre milk" → {"items":[{"action":"add","item":"milk","quantity":1000,"unit":"ml"}],"error_message":""}
"add 3 lb tomatoes" → {"items":[{"action":"add","item":"tomato","quantity":1362,"unit":"g"}],"error_message":""}
"add 2 tomatoes" → {"items":[{"action":"add","item":"tomato","quantity":2,"unit":"piece"}],"error_message":""}
"delete tomatoes" → {"items":[{"action":"delete","item":"tomato","quantity":0,"unit":"piece"}],"error_message":""}
"forget about the milk" → {"items":[{"action":"delete","item":"milk","quantity":0,"unit":"ml"}],"error_message":""}
"add 2 kg eggs" → {"items":[],"error_message":"Eggs are counted, not weighed."}
"add 3 rice" → {"items":[],"error_message":"Rice needs a weight, like 500 g or 1 kg."}

parameters.jsCode:
const out = $json.output ?? $json;
const src = $('Pantry-Update').first().json;

if (out.error_message) {
  return [{ json: {
    is_error: true,
    user_id: src.user_id,
    channel: src.channel,
    reply: `❌ ${out.error_message}`
  }}];
}

return out.items.map(i => ({
  json: { ...i, household_id: src.household_id, user_id: src.user_id, channel: src.channel }
}));

function fmt(q, unit) {
  if (unit === 'piece') return String(q);
  if (unit === 'g') {
    return q >= 454 ? (q / 454).toFixed(q % 454 === 0 ? 0 : 1) + ' lb'
                    : Math.round(q / 28) + ' oz';
  }
  if (unit === 'ml') {
    if (q >= 3785) return (q / 3785).toFixed(1) + ' gal';
    if (q >= 946)  return (q / 946).toFixed(1) + ' qt';
    return Math.round(q / 30) + ' fl oz';
  }
  return q + ' ' + unit;
}

if ($json.reply) {
  return [{ json: {
    user_id: $json.user_id,
    channel: $json.channel,
    reply: $json.reply
  }}];
}

const rows = $('Parse Items').all().map(i => i.json);

if (rows[0]?.is_error) {
  return [{ json: {
    user_id: rows[0].user_id,
    channel: rows[0].channel,
    reply: rows[0].reply
  }}];
}

const results = $('Upsert items').all().map(i => i.json);

const lines = rows.map((r, idx) => {
  if (r.action === 'delete') return `• ${r.item} — removed from pantry`;
  const after = Array.isArray(results[idx]) ? results[idx][0] : results[idx];
  if (r.action === 'remove' && after === 0) {
    return `• ${r.item} — now empty`;
  }
  return `• ${r.item} → ${fmt(after, r.unit)}`;
});

const verb = { add: 'Added', remove: 'Removed', set: 'Set', delete: 'Deleted' };
const action = rows[0]?.action ?? 'add';

return [{
  json: {
    user_id: rows[0].user_id,
    channel: rows[0].channel,
    reply: `${verb[action]} ✅\n${lines.join('\n')}`
  }
}];

const src = $('Pantry-Update').first().json;
const err = $json.error?.description ?? $json.error?.message ?? '';

const m = err.match(/Unit mismatch for (\w+): stored as (\w+), got (\w+)/);

let reply;
if (m) {
  const [, item, stored] = m;
  const label = stored === 'g' ? 'by weight (g, kg, lb or oz)'
              : stored === 'ml' ? 'by volume (ml, l or fl oz)'
              : 'by count';
  reply = `❌ ${item} is tracked ${label}. Use that, or say "delete ${item}" first if you want to switch.`;
} else {
  reply = "❌ Something went wrong adding that. Please try again.";
}

return [{ json: { user_id: src.user_id, channel: src.channel, reply } }];
